import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s2-u01")
C = "A1-A2"

L(1, "De manhã", "Acordar, levantar-se, tomar duche e o pequeno-almoço.",
  ["Descrever a rotina da manhã", "Usar 's ochtends e verbos como opstaan"],
  vocab=[V("v-wakker-worden","wakker worden","acordar","expression",note="ik word wakker"), V("v-opstaan","opstaan","levantar-se","verb",note="Separável: ik sta om zeven uur op."),
         V("v-douchen","douchen","tomar duche","verb",note="ik douche"), V("v-ontbijten","ontbijten","tomar o pequeno-almoço","verb",note="ik ontbijt"),
         V("v-tanden-poetsen","tandenpoetsen","lavar os dentes","verb",note="ik poets mijn tanden"), V("v-s-ochtends","'s ochtends","de manhã","adverb",note="Também 's morgens.")],
  ex=[("Ik word om zeven uur wakker.","Acordo às sete."),("Ik sta om half acht op.","Levanto-me às sete e meia.","«half acht» = 7h30!"),("'s Ochtends ontbijt ik met brood.","De manhã tomo o pequeno-almoço com pão.")],
  gram=[G("g-separaveis-intro","Verbos que se separam","Alguns verbos têm uma partícula que vai para o **fim da frase** no presente: **opstaan** → *ik **sta** om zeven uur **op***; **wakker worden** → *ik **word** wakker*. Veremos isto em detalhe na unidade 15.",
    [("Hij staat vroeg op.","Ele levanta-se cedo.")],
    "«Levantar-se» é reflexivo em português; «opstaan» não leva pronome.")],
  review=["v-om","v-uur","v-brood","v-koffie","v-eerst","v-daarna"],
  cefr=C, exs=[
    MA([("opstaan","levantar-se"),("douchen","tomar duche"),("ontbijten","tomar o pequeno-almoço"),("tandenpoetsen","lavar os dentes")], "A rotina da manhã.", ["v-opstaan","v-douchen","v-ontbijten","v-tanden-poetsen"]),
    WO("Levanto-me às sete.", ["Ik","sta","om","zeven","uur","op"], "A partícula «op» vai para o fim.", ["v-opstaan"]),
    FE(["Ik","opsta","om","zeven","uur."], 1, "sta … op", "No presente separa-se: ik sta om zeven uur op.", ["v-opstaan"]),
    CJ("douchen","ik","Ik ___ elke ochtend.", ["douche"], "douchen → ik douche.", ["v-douchen"]),
    CJ("ontbijten","hij","Hij ___ om acht uur.", ["ontbijt"], "A raiz já acaba em t: hij ontbijt.", ["v-ontbijten"]),
    TR("pt-nl","De manhã bebo café.", ["'s [Ochtends|ochtends|Morgens|morgens] drink ik koffie","Ik drink 's [ochtends|morgens] koffie"], "Começando por 's ochtends → inversão.", ["v-s-ochtends"]),
    TR("nl-pt","Ik word om zes uur wakker.", ["Acordo às seis( horas)"], "wakker worden = acordar.", ["v-wakker-worden"]),
    MC("O que significa «half acht»?", ["*7h30","8h30|Em neerlandês «half acht» = meia hora ANTES das oito.","8h00|Seria «acht uur»."], "half + hora seguinte: half acht = 7h30.", ["v-uur"]),
    LI("Eerst douche ik, daarna ontbijt ik.", ["Eerst douche ik(,) daarna ontbijt ik"], "Primeiro tomo duche, depois tomo o pequeno-almoço.", "Inversões depois de eerst/daarna.", ["v-douchen","v-ontbijten"]),
    CO("text","A manhã da Sanne", "Sanne wordt om half zeven wakker. Ze staat meteen op en ze douchet. Om zeven uur ontbijt ze met brood en thee. Daarna poetst ze haar tanden en fietst ze naar haar werk.",
       [("A que horas acorda a Sanne?", ["*Às 6h30","Às 7h30","Às 7h00"]),("O que bebe ao pequeno-almoço?", ["*Chá","Café","Leite"])],
       "«half zeven» = 6h30.", ["v-wakker-worden","v-ontbijten"]),
  ], diff=2, mins=6)

L(2, "No trabalho e na escola", "Começar, fazer pausa, almoçar e acabar.",
  ["Falar do horário de trabalho ou de estudo"],
  vocab=[V("v-werk","werk","trabalho","noun","het"), V("v-beginnen","beginnen","começar","verb",note="ik begin, het begint"),
         V("v-pauze","pauze","pausa|intervalo","noun","de"), V("v-lunchen","lunchen","almoçar","verb",note="ik lunch"),
         V("v-klaar","klaar","pronto|acabado","adjective",note="Ik ben klaar = acabei."), V("v-thuiswerken","thuiswerken","trabalhar a partir de casa","verb",note="ik werk thuis")],
  ex=[("Mijn werk begint om negen uur.","O meu trabalho começa às nove."),("Om twaalf uur lunch ik.","Ao meio-dia almoço."),("Om vijf uur ben ik klaar.","Às cinco acabo.")],
  gram=[G("g-lunch-cultura","O almoço neerlandês","Nos Países Baixos, o almoço é normalmente leve e rápido: **een broodje** (sandes) e leite ou café, muitas vezes na secretária ou numa **pauze** curta. A refeição quente é ao jantar (por volta das 18h).",
    [("Ik eet een broodje kaas.","Como uma sandes de queijo.")],
    "Em Portugal o almoço costuma ser uma refeição quente e mais longa.")],
  review=["v-werken","v-om","v-uur","v-school","v-thuis"],
  cefr=C, exs=[
    MA([("werk","trabalho"),("beginnen","começar"),("pauze","pausa"),("lunchen","almoçar"),("klaar","acabado")], "No trabalho.", ["v-werk","v-beginnen","v-pauze","v-lunchen","v-klaar"]),
    CJ("beginnen","mijn werk","Mijn werk ___ om negen uur.", ["begint"], "het werk begint.", ["v-beginnen"]),
    TR("pt-nl","Às cinco acabo.", ["Om vijf uur ben ik klaar","Ik ben om vijf uur klaar"], "klaar zijn = acabar.", ["v-klaar"]),
    TR("nl-pt","Ik werk op maandag thuis.", ["À segunda-feira trabalho em casa","Às segundas trabalho a partir de casa","Trabalho em casa à segunda(-feira)"], "op maandag = à segunda-feira.", ["v-thuiswerken"]),
    AR("werk","o trabalho","het", "«Het werk».", ["v-werk"]),
    AR("pauze","a pausa","de", "«De pauze».", ["v-pauze"]),
    FB("Om half één heb ik ___.", ["pauze"], "pauze hebben = ter intervalo.", ["v-pauze"], choices=["pauze","klaar","werk"], tr="Às meio-dia e meia tenho intervalo."),
    FE(["Om","twaalf","uur","ik","lunch."], 3, "lunch ik", "Inversão: om twaalf uur lunch ik.", ["v-lunchen"]),
    LI("Wanneer begint de les?", ["Wanneer begint de les"], "Quando começa a aula?", "de les = a aula.", ["v-beginnen"]),
    DL([("Colega","Ga je mee lunchen?","Vens almoçar?"),("Você","")], ["*Ja, graag! Ik heb om twaalf uur pauze.","Ja, ik ben lunchen.|Não faz sentido.","Nee, ik begin.|Incompleto e estranho."], "Aceitar e indicar a hora.", ["v-lunchen","v-pauze"]),
  ], diff=2, mins=6)

L(3, "À noite", "Cozinhar, jantar, ver televisão e ir dormir.",
  ["Descrever a rotina da noite"],
  vocab=[V("v-koken","koken","cozinhar","verb"), V("v-avondeten","avondeten","jantar","noun","het",note="Também verbo: we eten om zes uur = jantamos às seis."),
         V("v-tv-kijken","tv kijken","ver televisão","expression",note="ik kijk tv"), V("v-naar-bed","naar bed gaan","ir para a cama","expression"),
         V("v-s-avonds","'s avonds","à noite","adverb"), V("v-rusten","rusten","descansar","verb")],
  ex=[("'s Avonds kook ik.","À noite cozinho."),("We eten om half zeven.","Jantamos às seis e meia."),("Om elf uur ga ik naar bed.","Às onze vou para a cama.")],
  gram=[G("g-s-tijden","'s ochtends, 's middags, 's avonds, 's nachts","Estas formas significam «de manhã», «à tarde», «à noite» e «de madrugada/à noite». O **'s** é uma forma antiga de «des». No início da frase escreve-se **'s Avonds** (maiúscula na segunda letra).",
    [("'s Middags werk ik.","À tarde trabalho."),("'s Nachts slaap ik.","À noite (de madrugada) durmo.")])],
  review=["v-s-ochtends","v-eten","v-gaan","v-slapen"],
  cefr=C, exs=[
    MA([("koken","cozinhar"),("avondeten","jantar"),("tv kijken","ver televisão"),("rusten","descansar")], "À noite.", ["v-koken","v-avondeten","v-tv-kijken","v-rusten"]),
    TR("pt-nl","À noite vejo televisão.", ["'s [Avonds|avonds] kijk ik tv","Ik kijk 's avonds tv"], "Inversão depois de 's avonds.", ["v-s-avonds","v-tv-kijken"]),
    TR("nl-pt","Om elf uur ga ik naar bed.", ["Às onze( horas) vou [para a cama|dormir]","Às onze( horas) deito-me"], "naar bed gaan = ir para a cama.", ["v-naar-bed"]),
    AR("avondeten","o jantar","het", "«Het avondeten».", ["v-avondeten"]),
    CJ("koken","wie","Wie ___ vanavond?", ["kookt"], "koken → hij kookt (ko-ken → kook).", ["v-koken"]),
    FB("We eten om ___ zeven: om half zeven.", ["half"], "half zeven = 6h30.", ["v-avondeten"], choices=["half","kwart","halve"], tr="Jantamos às seis e meia."),
    FE(["'s Avonds","ik","kijk","tv."], 1, "kijk ik", "Inversão: 's avonds kijk ik tv.", ["v-s-avonds"]),
    LI("Wat eten we vanavond?", ["Wat eten we vanavond"], "O que jantamos hoje?", "vanavond = esta noite.", ["v-avondeten"]),
    WO("Às dez descanso um pouco.", ["Om","tien","uur","rust","ik","een","beetje"], "Inversão depois da hora.", ["v-rusten"], alt=["Ik rust om tien uur een beetje"]),
    MC("A que horas se janta normalmente nos Países Baixos?", ["*Por volta das 18h","Por volta das 21h|É mais típico em Portugal ou Espanha.","À meia-noite|Não."], "O jantar neerlandês é cedo.", ["v-avondeten"]),
  ], diff=2, mins=6)

L(4, "O fim de semana", "Dormir até tarde, fazer compras, desporto e visitas.",
  ["Falar do fim de semana"],
  vocab=[V("v-weekend","weekend","fim de semana","noun","het"), V("v-uitslapen","uitslapen","dormir até tarde","verb",note="Separável: ik slaap uit."),
         V("v-boodschappen","boodschappen doen","fazer compras (de supermercado)","expression"), V("v-sporten","sporten","fazer desporto","verb"),
         V("v-op-bezoek","op bezoek gaan","visitar|ir de visita","expression",note="op bezoek gaan bij = visitar alguém")],
  ex=[("In het weekend slaap ik uit.","Ao fim de semana durmo até tarde."),("Op zaterdag doe ik boodschappen.","Ao sábado faço compras."),("Zondag gaan we op bezoek bij oma.","No domingo vamos visitar a avó.")],
  review=["v-gaan","v-doen","v-oma","v-samen"],
  cefr=C, exs=[
    MA([("weekend","fim de semana"),("uitslapen","dormir até tarde"),("sporten","fazer desporto"),("boodschappen doen","fazer compras")], "Fim de semana.", ["v-weekend","v-uitslapen","v-sporten","v-boodschappen"]),
    WO("Ao fim de semana durmo até tarde.", ["In","het","weekend","slaap","ik","uit"], "Separável: slaap … uit.", ["v-uitslapen","v-weekend"], alt=["Ik slaap in het weekend uit"]),
    TR("pt-nl","Ao sábado faço compras.", ["Op zaterdag doe ik boodschappen","Ik doe op zaterdag boodschappen","Zaterdag doe ik boodschappen"], "boodschappen doen.", ["v-boodschappen"]),
    TR("nl-pt","Zondag gaan we op bezoek bij oma.", ["No domingo vamos visitar a avó","Domingo vamos visitar a avó","No domingo vamos a casa da avó"], "op bezoek gaan bij = visitar.", ["v-op-bezoek","v-oma"]),
    AR("weekend","o fim de semana","het", "«Het weekend».", ["v-weekend"]),
    FB("Ik ___ twee keer per week: ik zwem en ik fiets.", ["sport"], "sporten → ik sport.", ["v-sporten"], choices=["sport","slaap uit","kook"], tr="Faço desporto duas vezes por semana: nado e ando de bicicleta."),
    FE(["Ik","uitslaap","in","het","weekend."], 1, "slaap … uit", "Separável: ik slaap in het weekend uit.", ["v-uitslapen"]),
    DL([("Eva","Wat doe je dit weekend?","O que fazes este fim de semana?"),("Tom","")], ["*Ik slaap uit en ik ga sporten.","Ik ben weekend.|Não faz sentido.","Om zeven uur.|Responde a «hoe laat?»."], "Responde-se com atividades.", ["v-uitslapen","v-sporten"]),
    LI("Wat doe je in het weekend?", ["Wat doe je in het weekend"], "O que fazes ao fim de semana?", "in het weekend = ao fim de semana.", ["v-weekend"]),
    SW("Escreva 2–3 frases sobre o seu fim de semana típico.", ["In het weekend slaap ik uit(.) Op zaterdag doe ik boodschappen"],
       ["Usa «in het weekend» ou dias da semana","Inversão depois de expressões de tempo","Verbos separáveis com a partícula no fim"], 6, "Modelo: «In het weekend slaap ik uit. Op zaterdag doe ik boodschappen en op zondag ga ik op bezoek bij mijn ouders.»", ["v-weekend"]),
  ], diff=2, mins=6)

L(5, "Um dia normal", "Revisão: a rotina do início ao fim.",
  ["Contar um dia completo por ordem"],
  ex=[("Ik sta op, ik douche, ik ontbijt en dan ga ik naar mijn werk.","Levanto-me, tomo duche, tomo o pequeno-almoço e depois vou trabalhar.")],
  review=["v-opstaan","v-douchen","v-ontbijten","v-beginnen","v-lunchen","v-koken","v-naar-bed","v-s-ochtends","v-s-avonds"],
  cefr=C, exs=[
    WO("Primeiro levanto-me, depois tomo duche.", ["Eerst","sta","ik","op,","daarna","douche","ik"], "Inversões e partícula «op».", ["v-opstaan","v-douchen"]),
    MC("Qual é a ordem lógica?", ["*opstaan – ontbijten – werken – koken – naar bed gaan","koken – opstaan – naar bed gaan – werken|Ordem ilógica.","naar bed gaan – opstaan – koken|Ordem ilógica."], "Um dia típico.", ["v-opstaan"]),
    TR("pt-nl","À noite cozinho e depois vejo televisão.", ["'s [Avonds|avonds] kook ik en daarna kijk ik tv","'s [Avonds|avonds] kook ik en dan kijk ik tv"], "Inversões.", ["v-koken","v-tv-kijken"]),
    TR("nl-pt","Mijn werk begint om half negen.", ["O meu trabalho começa às oito e meia","O meu trabalho começa às 8h30"], "half negen = 8h30.", ["v-beginnen"]),
    FE(["Wij","staat","om","zeven","uur","op."], 1, "staan", "Com «wij» o verbo fica no plural: wij staan om zeven uur op.", ["v-opstaan"]),
    LI("Om twaalf uur heb ik pauze.", ["Om twaalf uur heb ik pauze"], "Ao meio-dia tenho intervalo.", "Inversão depois da hora.", ["v-pauze"]),
    CO("text","O dia do Lukas", "Lukas staat om zes uur op, want hij begint om zeven uur. Hij werkt in een bakkerij. Om elf uur heeft hij pauze en eet hij een broodje. Om drie uur is hij klaar. 's Middags slaapt hij een uur en 's avonds kookt hij voor zijn gezin.",
       [("Porque se levanta cedo o Lukas?", ["*Começa a trabalhar às sete","Gosta de acordar cedo","Leva os filhos à escola"]),("Onde trabalha?", ["*Numa padaria","Num hospital","Numa escola"]),("O que faz à tarde?", ["*Dorme uma hora","Faz desporto","Cozinha"])],
       "bakkerij = padaria.", ["v-opstaan","v-klaar","v-koken"]),
    SW("Descreva o seu dia (5 frases) com horas: levantar, trabalhar/estudar, almoçar, jantar, deitar.", ["Ik sta om zeven uur op(.) Om negen uur begin ik(.) Om twaalf uur lunch ik(.) Om zes uur eet ik(.) Om elf uur ga ik naar bed"],
       ["Pelo menos 4 horas diferentes (om … uur, half …)","Inversão depois de «om … uur»","Partícula de «opstaan» no fim"], 15, "Compare a ordem das palavras com o modelo.", ["v-opstaan"]),
    MA([("'s ochtends","de manhã"),("'s middags","à tarde"),("'s avonds","à noite"),("'s nachts","de madrugada")], "Partes do dia.", ["v-s-ochtends","v-s-avonds"]),
  ], diff=2, mins=7)

W()
